// 推荐：将失败次数和锁定时间存储在服务端，前端仅做展示和请求
const loginAttempt = async (username, password) => {
  const res = await api.login({ username, password });
  if (res.code === 'ACCOUNT_LOCKED') {
    const remaining = Math.ceil((res.lockUntil - Date.now()) / 60000);
    showError(`账户已锁定，请${remaining}分钟后重试`);
    return;
  }
  // 处理其他错误
};

// 若前端需临时缓存失败次数（仅作辅助提示），使用localStorage并配合时间戳
const STORAGE_KEY = 'login_failures';
const MAX_ATTEMPTS = 5;
const LOCK_DURATION = 15 * 60 * 1000;

function getFailureInfo(username) {
  const key = `${STORAGE_KEY}_${username}`;
  const data = JSON.parse(localStorage.getItem(key) || '{}');
  if (data.count >= MAX_ATTEMPTS && Date.now() - data.firstFailTime < LOCK_DURATION) {
    return { locked: true, remaining: Math.ceil((LOCK_DURATION - (Date.now() - data.firstFailTime)) / 60000) };
  }
  return { locked: false };
}
